                                                              c(
                                                                  "export-route-target" (  /* Export Route Target (RT) in the network-instance on a PE. */
                                                                    time_of_day  /* Export Route Target (RT) in the network-instance on a PE. */
                                                                  ),
                                                                  "import-route-target" (  /* Import Route Target (RT) in the network-instance on a PE. */
                                                                    time_of_day  /* Import Route Target (RT) in the network-instance on a PE. */
                                                                  )
                                                              )
                                                          )
                                                      )
