                                                              c(
                                                                  "vni" arg  /* Virtual Network Identifier (VNI) associated to the EVI. This VNI is used for ingress and egress in the VXLAN domain. */,
                                                                  "overlay-endpoint-network-instance" arg  /* The network instance to resolve the overlay-endpoint within. */,
                                                                  "overlay-endpoint" arg  /* Associate the EVI with an VXLAN Endpoint defined under connection points. The network instance to resolve the overlay-endpoint within. */,
                                                                  "host-reachability-bgp" (  /* Enable or Disable the BGP control plane to be used to exchange  updates from the NVE interface */
                                                                    ("true" | "false")
                                                                  ),
                                                                  "multicast-group" (  /* Multicast group address for BUM traffic */
                                                                    time_of_day  /* Multicast group address for BUM traffic */
                                                                  ),
                                                                  "multicast-mask" (  /* Multicast group address mask */
                                                                    time_of_day  /* Multicast group address mask */
                                                                  )
                                                              )
                                                          ),
                                                          "anycast-source-interface" (  /* Anycast source interface references */
                                                              c(
                                                                  "config" (  /* Anycast source interface configuration references */
                                                                      c(
                                                                          "interface" arg  /* Reference to a base interface.  If a reference to a subinterface is required, this leaf must be specified to indicate the base interface. */,
                                                                          "subinterface" arg  /* Reference to a subinterface -- this requires the base interface to be specified using the interface leaf in this container.  If only a reference to a base interface is requuired, this leaf should not be set. */
                                                                      )
                                                                  )
                                                              )
                                                          )
                                                      )
                                                  ),
                                                  "pbb" (  /* Container for EVPN with PBB PE functionality for scaling over MPLS, */
                                                      c(
                                                          "b-component" (  /* List of B-components. The b-component learns and forwards traffic on the backbone in order to reduce the number of BGP MAC Advertisement routes by aggregating Customer/Client MAC (C-MAC) addresses via Provider Backbone MAC (B-MAC) address. */
                                                              s(
                                                                      arg,
                                                                c(
                                                                  "config" (  /* Configuration variables for the b-components. */
                                                                      c(
                                                                          "b-component-name" arg  /* Type of the associated b-component */,
                                                                          "backbone-src-mac" arg  /* EVPN will run independently in both components, the I-component MAC-VRF and B-component MAC-VRF. The backbone-src-mac assigns the b-component MAC. */
                                                                      )
                                                                  ),
                                                                  "i-components" (  /* i-components container definition. */
                                                                      c(
                                                                          "i-component" (  /* list of i-components */
                                                                              s(
                                                                                      arg,
                                                                                c(
                                                                                  "config" (  /* Configuration variables for the i-sid */
                                                                                      c(
                                                                                          "i-sid" arg  /* Service Instance Identifier 24 bits and global within a PBB network. I-SID defines the service instance that the frame should be mapped to. */
                                                                                      )
                                                                                  )
                                                                                )
                                                                              )
                                                                          )
                                                                      )
                                                                  )
                                                                )
                                                              )
                                                          )
                                                      )
