                                              c(
                                                  "config" (  /* Configuration data for the Ethernet Segments. */
                                                      c(
                                                          "name" arg  /* Ethernet Segment name */,
                                                          "esi-type" (  /* ESI Type is a 1-octet field (most significant octet) that specifies the format of the remaining 9 octets (ESI Value). */
                                                            ("TYPE_0_OPERATOR_CONFIGURED" | "TYPE_1_LACP_BASED" | "TYPE_2_BRIDGE_PROTOCOL_BASED" | "TYPE_3_MAC_BASED" | "TYPE_4_ROUTER_ID_BASED" | "TYPE_5_AS_BASED")
                                                          ),
                                                          "esi" (  /* Ethernet Segment Identifier (ESI) value. For ESI Type 0: The esi leaf value is directly configured by the operator. For ESI Type 1: The AUTO enum must be used. For ESI Type 2: The AUTO enum must be used. For ESI Type 3: The directly configured or AUTO enum must be used. For ESI Type 4: The directly configured or AUTO enum must be used. For ESI Type 5: The directly configured or AUTO enum must be used. */
                                                            time_of_day  /* Ethernet Segment Identifier (ESI) value. For ESI Type 0: The esi leaf value is directly configured by the operator. For ESI Type 1: The AUTO enum must be used. For ESI Type 2: The AUTO enum must be used. For ESI Type 3: The directly configured or AUTO enum must be used. For ESI Type 4: The directly configured or AUTO enum must be used. For ESI Type 5: The directly configured or AUTO enum must be used. */
                                                          ),
                                                          "redundancy-mode" (  /* Multihoming options for load balancing of traffic in the Ethernet Segment. */
                                                            ("ALL_ACTIVE" | "SINGLE_ACTIVE")
                                                          ),
                                                          "interface" arg  /* Reference to a base interface.  If a reference to a subinterface is required, this leaf must be specified to indicate the base interface. */,
                                                          "subinterface" arg  /* Reference to a subinterface -- this requires the base interface to be specified using the interface leaf in this container.  If only a reference to a base interface is requuired, this leaf should not be set. */
                                                      )
                                                  ),
                                                  "df-election" (  /* Top container for the configuration and state parameters for the Designated forwarding Election */
                                                      c(
                                                          "config" (  /* Configuration parameters for the Designated forwarding Election */
                                                              c(
                                                                  "df-election-method" (  /* Select the Designated Forwarder Election (DF) election method */
                                                                    ("DEFAULT" | "HIGHEST_RANDOM_WEIGHT" | "PREFERENCE")
                                                                  ),
                                                                  "preference" arg  /* Defines a 2-octet value that indicates the PE preference to become the DF in the Ethernet-Segment. */,
                                                                  "revertive" (  /* The 'preempt' or 'revertive' behavior. This option will allow a non-revertive behavior in the DF election. */
                                                                    ("true" | "false")
                                                                  ),
                                                                  "election-wait-time" arg  /* Designated Forwarder Election wait-time. When the DF timer expires, the PE device selects the DF based on the highest preference value */
                                                              )
                                                          )
                                                      )
                                                  )
                                              )
                                          )
                                      )
                                  )
                              )
                          ),
                          "encapsulation" (  /* Configuration parameters relating to the encapsulation used for the network instance */
                              c(
                                  "config" (  /* Configuration parameters relating to the encapsulation of the network instance */
                                      c(
                                          "encapsulation-type" (  /* The on-the-wire encapsulation that should be used when sending traffic from this network instance */
                                            ("VXLAN" | "MPLS")
                                          ),
                                          "label-allocation-mode" (  /* The label allocation mode to be used for L3 entries in the network instance */
                                            ("INSTANCE_LABEL" | "PER_NEXTHOP" | "PER_PREFIX")
                                          ),
                                          "control-word" (  /* Whether the control-word should be used for the network instance */
                                            ("true" | "false")
                                          )
                                      )
                                  )
                              )
                          ),
                          "inter-instance-policies" (  /* Policies dictating how RIB or FIB entries are imported to and exported from this instance */
                              c(
                                  "apply-policy" (  /* Anchor point for routing policies in the model. Import and export policies are with respect to the local routing table, i.e., export (send) and import (receive), depending on the context. */
                                      c(
                                          "config" (  /* Policy configuration data. */
                                              c(
                                                  "import-policy" arg  /* list of policy names in sequence to be applied on receiving a routing update in the current context, e.g., for the current peer group, neighbor, address family, etc. */,
                                                  "default-import-policy" (  /* explicitly set a default policy if no policy definition in the import policy chain is satisfied. */
                                                    ("ACCEPT_ROUTE" | "REJECT_ROUTE")
                                                  ),
                                                  "export-policy" arg  /* list of policy names in sequence to be applied on sending a routing update in the current context, e.g., for the current peer group, neighbor, address family, etc. */,
                                                  "default-export-policy" (  /* explicitly set a default policy if no policy definition in the export policy chain is satisfied. */
                                                    ("ACCEPT_ROUTE" | "REJECT_ROUTE")
                                                  )
                                              )
                                          )
                                      )
                                  ),
                                  "import-export-policy" (  /* Top container to set the import and export policies associated with a EVI */
                                      c(
                                          "config" (  /* Configuration parameters to set the import and export policies associated with a EVI */
                                              c(
                                                  "export-route-target" (  /* Export Route Target (RT) in the network-instance on a PE. */
                                                    time_of_day  /* Export Route Target (RT) in the network-instance on a PE. */
                                                  ),
                                                  "import-route-target" (  /* Import Route Target (RT) in the network-instance on a PE. */
                                                    time_of_day  /* Import Route Target (RT) in the network-instance on a PE. */
                                                  )
                                              )
                                          )
                                      )
                                  )
                              )
                          ),
                          "table-connections" (  /* Policies dictating how RIB or FIB entries are propagated between tables */
                              c(
                                  "table-connection" (  /* A list of connections between pairs of routing or forwarding tables, the leaking of entries between which is specified by the import policy. A connection connecting a source table to a destination table implies that routes that match the policy specified for the connection are available for the destination protocol to advertise, or match within its policies. */
                                      s(
                                              ("IGMP" | "PIM" | "LOCAL_AGGREGATE" | "DIRECTLY_CONNECTED" | "STATIC" | "OSPF3" | "OSPF" | "ISIS" | "BGP"),
                                              ("IGMP" | "PIM" | "LOCAL_AGGREGATE" | "DIRECTLY_CONNECTED" | "STATIC" | "OSPF3" | "OSPF" | "ISIS" | "BGP"),
                                              ("L2_ETHERNET" | "MPLS" | "IPV6" | "IPV4"),
                                        c(
                                          "config" (  /* Configuration parameters relating to the connection between tables */
                                              c(
                                                  "src-protocol" (  /* The source protocol for the table connection */
                                                    ("IGMP" | "PIM" | "LOCAL_AGGREGATE" | "DIRECTLY_CONNECTED" | "STATIC" | "OSPF3" | "OSPF" | "ISIS" | "BGP")
                                                  ),
                                                  "address-family" (  /* The address family associated with the connection. This must be defined for the source protocol. The target address family is implicitly defined by the address family specified for the source protocol. */
                                                    ("L2_ETHERNET" | "MPLS" | "IPV6" | "IPV4")
                                                  ),
                                                  "dst-protocol" (  /* The destination protocol for the table connection */
                                                    ("IGMP" | "PIM" | "LOCAL_AGGREGATE" | "DIRECTLY_CONNECTED" | "STATIC" | "OSPF3" | "OSPF" | "ISIS" | "BGP")
                                                  ),
                                                  "disable-metric-propagation" (  /* By default a system may reflect the metric specified in the destination protocol according to that which is set in the source protocol. For example: - IS-IS metric may be reflected in BGP MED (and vice versa) - OSPF metric may be reflected in the BGP MED (and vice versa) When this leaf is set to true, this reflection behaviour MUST be disabled, and rather the metric must be set to the default value, or explicitly set by policy. */
                                                    ("true" | "false")
                                                  ),
                                                  "import-policy" arg  /* list of policy names in sequence to be applied on receiving a routing update in the current context, e.g., for the current peer group, neighbor, address family, etc. */,
                                                  "default-import-policy" (  /* explicitly set a default policy if no policy definition in the import policy chain is satisfied. */
                                                    ("ACCEPT_ROUTE" | "REJECT_ROUTE")
                                                  )
                                              )
                                          )
                                        )
