                                        c(
                                          "config" (  /* Configuration parameters relating to the associated interface */
                                              c(
                                                  "id" arg  /* A unique identifier for this interface - this is expressed as a free-text string */,
                                                  "interface" arg  /* Reference to a base interface.  If a reference to a subinterface is required, this leaf must be specified to indicate the base interface. */,
                                                  "subinterface" arg  /* Reference to a subinterface -- this requires the base interface to be specified using the interface leaf in this container.  If only a reference to a base interface is requuired, this leaf should not be set. */,
                                                  "associated-address-families" (  /* The address families on the subinterface which are to be associated with this network instance. When this leaf-list is empty and the network instance requires Layer 3 information the address families for which the network instance is enabled should be imported. If the value of this leaf-list is specified then the association MUST only be made for those address families that are included in the list. */
                                                    ("L2_ETHERNET" | "MPLS" | "IPV6" | "IPV4")
