                                                "osc-fiber-loss-low-tca" (  /* OSC fiber loss low TCA */
                                                    c(
                                                        "enable-tca"  /* Enable tca */,
                                                        "no-enable-tca"  /* Don't enable tca */,
                                                        "threshold" arg  /* Threshold for 15 minute osc fiber loss low TCA in dBm */,
                                                        "threshold-24hrs" arg  /* Threshold for 24 hour osc fiber loss low TCA in dBm */
                                                    )
                                                )
                                            )
                                        )
                                    )
                                )
                            )
                        )
                    )
                )
            )
        ),
        "power" (  /* Power FPCs on or off */
          ("off" | "on")
        ),
        "no-vlan-tagging"  /* Disable vlan support on FPC with default tpid 0x8100 */,
        "traffic-manager" (  /* Configure traffic-manager attributes */
            c(
                "buffer-monitor-enable"  /* Enable port buffer monitoring */,
                "queue-threshold" (  /* Set queue thresholds */
                    c(
                        "fabric-queue" (  /* Set fabric queue thresholds */
                            c(
                                "priority" enum(("low" | "high")) (  /* Queue priority */
                                    c(
                                        "threshold" arg  /* Threshold percentage to be set */
                                    )
                                )
                            )
                        ),
                        "wan-queue" (  /* Set wan queue thresholds */
                            c(
                                "priority" enum(("low" | "medium-low" | "medium-high" | "high")) (  /* Queue Priority */
                                    c(
                                        "threshold" arg  /* Threshold percentage to be set */
                                    )
                                )
                            )
                        )
                    )
                ),
                "enhanced-priority-mode"  /* Enable enhanced priority mode */,
                "no-enhanced-priority-mode"  /* Don't enable enhanced priority mode */,
                "packet-timestamp" (  /* Configure collecting CoS last packet enqueued timestamp */
                  ("enable" | "disable")
                )
            )
        ),
        "max-power" arg  /* Max power to be consumed by MPC */,
        "route-localization" (  /* Route-Localization fib-remote or fib-local */
          ("fib-remote" | "fib-local")
        ),
        "vpn-localization" (  /* VPN-localization core-facing-only  or core-facing-default */
          ("vpn-core-facing-only" | "vpn-core-facing-default")
        ),
        "power-budget-priority" arg  /* FPC priority number */,
        c(
          "disable-power"  /* Do not provide power to the card */,
          "allow-sram-parity-errors"  /* Do not power cycle FPC when SRAM parity errors occur */
        ),
        c(
          "performance-mode" (  /* Enable performance mode, FPC will restart if mode changes from lite mode to performance mode */
              c(
                  "number-of-ucode-workers" arg  /* Configure number of ucode worker cores, FPC will restart if there is a change in number of ucode worker cores */
              )
          ),
          "lite-mode"  /* Enable lite mode, FPC will restart if mode changes from performance mode to lite mode */
        ),
        "services-offload"  /* Enable services offload on fpc */,
        "cfp-to-et"  /* Enable ET interface and remove CFP client */,
        "lossless-flow-control" (  /* Lossless buffer config for Ethernet Mac pause */
            c(
                c(
                  "lossless-flow-control-enable"  /* Enable Lossless buffer config for Ethernet Mac pause */,
                  "no-lossless-flow-control-enable"  /* Disable Lossless buffer config for Ethernet Mac pause */
                )
            )
        ),
        "np-cache"  /* Enable NP cache and services offload on fpc */,
        "np-cache-disable"  /* Disable NP cache and services offload on fpc */,
        "offline"  /* Keep FPC offline */,
        "offline-on-fabric-bandwidth-reduction"  /* Bring FPC offline when running with reduced fabric bandwidth */,
        "ir-mode" (  /* Configure IR or R mode for MPC4 and above cards */
          ("IR" | "R")
        ),
        "no-loss" (  /* PFC lossless buffer configuratios */
            c(
                "buffer" (  /* PFC lossless buffer */
                    c(
                        "percentage" arg  /* Configure buffer space for lossless traffic handling */
                    )
                )
            )
        ),
        "license-mode" (  /* Configure license mode for PTX FPC3 and later cards */
          ("r" | "ir" | "lsr" | "ip")
        ),
        "fabric" (
            c(
                "loopback" (  /* Set fpc fabric loopback mode */
                    c(
                        "wan" (  /* Enable/Disable fpc fabric  wan loopback */
                          ("off" | "on")
                        )
                    )
                ),
                "blackhole-action" (  /* Action taken upon fabric plane blackhole involving the FPC */
                  ("log-only" | "offline" | "restart" | "restart-then-offline")
                ),
                "bandwidth-degradation" (  /* Take FPC recovery action when FPC running with reduced fabric bandwidth */
                    c(
                        "percentage" arg  /* The percentage of PFE bandwidth degradation to trigger action */,
                        "no-fabric-switchover"  /* Do not perform switchover to spare CB */,
                        "action" (  /* Type of action to trigger */
                          ("log-only" | "offline" | "restart" | "restart-then-offline")
                        )
                    )
                )
            )
        ),
        "port-mirror-instance" arg,
        "sampling-instance" arg,
        "inline-services" (
            c(
                "report-zero-oif-gw-on-discard"  /* Jflow reports value zero in OIF and GW when traffic is not forwarded */,
                "flex-flow-sizing"  /* No fixed size allocation of flow tables for proto families */,
                "use-extended-flow-memory"  /* Use extended memory for flow records */,
                "flow-table-size" (
                    c(
                        "ipv4-flow-table-size" arg  /* IPv4 flow table size in units of 256k */,
                        "ipv6-flow-table-size" arg  /* IPv6 flow table size in units of 256k */,
                        "vpls-flow-table-size" arg  /* VPLS flow table size in units of 256k */,
                        "bridge-flow-table-size" arg  /* BRIDGE flow table size in units of 256k */,
                        "ipv6-extended-attrib"  /* Enable extended flow attribute */,
                        "mpls-flow-table-size" arg  /* MPLS flow table size in units of 256k */
                    )
                ),
                "no-inline-jflow"  /* Disable Inline-Jflow on the SPC3 Linecard */
            )
        ),
        "inline-video-monitoring" (
            c(
                "maximum-flows-count" arg  /* Maximum number of inline video monitoring flows per PFE instance. */,
                "flow-table-size" arg  /* Size of flow table size per PFE instance */
            )
        ),
        "application-services" (  /* Application services configuration */
            c(
                "package" arg  /* Package selection */
            )
        ),
        "slamon-services" (  /* SLA monitoring services */
            c(
                "rfc2544"  /* Enable sla monitoring services */
            )
        ),
        "flexible-queuing-mode"  /* Enable flexible queuing mode */,
        "loopback-device-count" arg  /* Number of loopbacks */,
        "interasic-linkerror-recovery-enable"  /* Enable inter-asic link error recovery */,
        "number-of-ports" (  /* Number of physical ports to enable on FPC */
          ("8" | "12")
        ),
        "pfe" (  /* Packet forwarding engine parameters */
          chassis_pfe_type  /* Packet forwarding engine parameters */
        ),
        "service-package" (  /* Service package to be loaded on FPC */
          ("bundle-rfc2544" | "bundle-nat-ipsec" | "bundle-ptp-enterprise-profile")
        ),
        "max-queues" (  /* Maximum number of queues configurable on FPC */
          ("8k" | "16k" | "32k" | "48k" | "64k" | "96k" | "128k" | "192k" | "256k" | "384k" | "512k" | "768k" | "1M" | "1536k" | "2M")
        ),
        "bandwidth" (  /* Configure bandwidth of FPC */
          ("1.6T")
        ),
        "pfe-bandwidth" (  /* Configure per PFE bandwidth */
          ("240G" | "300G" | "400G")
        ),
        "error" (  /* Error level configuration for FPC */
          chassis_fpc_error_type  /* Error level configuration for FPC */
        ),
        "ether-type" arg (  /* Set Ethernet type on FPC */
            c(
                arg  /* Ether type */
            )
        ),
        "slc" (  /* Sub-line card (SLC) */
          chassis_slc_type  /* Sub-line card (SLC) */
        ),
        "low-power-mode"  /* Configure FPC low power mode */,
        "openflow" (  /* Openflow configuration */
            c(
                "access-list-partition" arg  /* Space reserved for openflow access-list rules */,
                "buffer-partition" arg  /* Buffer space reserved for openflow traffic */
            )
        )
    )
  )
end

