                        "bandwidth" (  /* Amount of bandwidth reserved for inline service */
                          ("1g" | "10g" | "20g" | "30g" | "40g" | "50g" | "60g" | "70g" | "80g" | "90g" | "100g" | "200g" | "300g" | "400g" | "480g" | arg)
                        )
                    )
                ),
                "bandwidth" (  /* Amount of bandwidth reserved for inline service */
                  ("1g" | "10g" | "20g" | "30g" | "40g" | "50g" | "60g" | "70g" | "80g" | "90g" | "100g" | "200g" | "300g" | "400g" | "480g" | arg)
                ),
                "fragmentation-mtu" arg  /* Set the fragmentation MTU size */,
