                                    "package" arg  /* Extension provider package to run on the PIC */,
                                    "syslog" enum(("external" | "pfe" | "daemon" | "kernel")) (  /* System logging facility */
                                        c(
                                            c(
                                              "any"  /* All levels */,
                                              "emergency"  /* Panic conditions */,
                                              "alert"  /* Conditions that should be corrected immediately */,
                                              "critical"  /* Critical conditions */,
                                              "error"  /* Error conditions */,
                                              "warning"  /* Warning messages */,
                                              "notice"  /* Conditions that should be handled specially */,
                                              "info"  /* Informational messages */,
                                              "none"  /* No messages */
