rule(:ggsn_pgw_apn) do
  arg.as(:arg) (
    c(
        "maximum-bearers" arg  /* Maximum bearers for the APN */,
        "wait-accounting"  /* Wait for accounting response for session creation */,
        "block-visitors"  /* Do not allow visitors connect to the APN */,
        "allow-network-behind-mobile"  /* Allow routing behind MS */,
        "local-policy-profile" arg  /* Local profile for the apn */,
        "apn-type" (  /* Specify APN type */
          ("real" | "virtual" | "virtual-pre-authenticate")
        ),
        "description" arg  /* Text description of APN */,
        "apn-data-type" (  /* Specify APN data type */
          ("ipv4" | "ipv6" | "ipv4v6")
        ),
        "mobile-interface" (
          interface_unit
        ),
        "address-assignment" (  /* Specify address assignment options */
            c(
                c(
                  "aaa"  /* AAA assigns addresses */,
                  "local" (  /* Gateway assigns addresses locally */
                      c(
                          "aaa-override"  /* Override local address by address from AAA */
                      )
                  ),
                  "dhcp-proxy-client" (  /* Gateway assigns address received when acting as DHCP proxy client */
                      c(
                          "aaa-override"  /* Override address received from DHCP proxy client mechanism by address from AAA */
                      )
                  )
                ),
                "inet-pool" (  /* Specify address group name or pool name for IPv4 */
                    c(
                        "group" arg,
                        "pool" arg,
                        "exclude-pools" arg  /* Names of pool to exclude */
                    )
                ),
                "inet6-pool" (  /* Specify address group name or pool name for IPv6 */
                    c(
                        "group" arg,
                        "pool" arg,
                        "exclude-v6pools" arg  /* Names of pool to exclude */
                    )
                ),
                "dhcpv4-proxy-client-profile" (  /* DHCPv4 proxy client profile for this APN */
                    c(
                        "logical-system" arg  /* Logical system where this DHCP proxy client profile is defined. If this option is not specified, default logical-system will be used */,
                        "routing-instance" arg  /* Routing-instance where this DHCP proxy client profile is defined. If this option is not specified, default routing-instance will be used */,
                        "profile-name" arg  /* Name of DHCP proxy client profile */,
                        "pool-name" arg  /* Name of the pool to be sent to DHCP server. It is optional */
                    )
                ),
                "dhcpv6-proxy-client-profile" (  /* DHCPv6 proxy client profile for this APN */
                    c(
                        "logical-system" arg  /* Logical system where this DHCP proxy client profile is defined. If this option is not specified, default logical-system will be used */,
                        "routing-instance" arg  /* Routing-instance where this DHCP proxy client profile is defined. If this option is not specified, default routing-instance will be used */,
                        "profile-name" arg  /* Name of DHCP proxy client profile */,
                        "pool-name" arg  /* Name of the pool to be sent to DHCP server. It is optional */
                    )
                ),
                "allow-static-ip-address" (  /* Allow user equipment provided static address */
                    c(
                        "no-aaa-verify"  /* Do not verify the address provided by user equipment through AAA */
                    )
                )
            )
        ),
        "session-timeout" arg  /* Session timeout value */,
        "idle-timeout" arg  /* Idle timeout value */,
        "idle-timeout-direction" (  /* Specific idle timeout direction */
          ("uplink" | "both")
        ),
        "restriction-value" arg  /* Restriction value */,
        "aaa-profile" arg  /* Specify AAA profile for Authorization and Accounting */,
        "user-options" (  /* Specify user options */
            c(
                c(
                  "user-name" arg  /* Default user name for user authentication */,
                  "use-msisdn"  /* Use msisdn for user authentication */,
                  "use-imsi"  /* Use imsi for user authentication */,
                  "use-apnname"  /* Use APN name for user authentication */
                ),
                "password" (  /* Default user password for user authentication */
                  unreadable  /* Default user password for user authentication */
                ),
                "override-pco"  /* Override the username and password received in PCO */
            )
        ),
        "charging" (  /* Default charging profiles */
            c(
                "default-profile" arg  /* Default charging profile for the APN */,
                "home-profile" arg  /* Default home profile for the APN */,
                "roamer-profile" arg  /* Default roamer profile for the APN */,
                "visitor-profile" arg  /* Default visitor profile for the APN */,
                "profile-selection-order" (  /* Default charging profile selection order */
                  ("radius" | "static" | "serving")
                )
            )
        ),
        "dns-server" (  /* Specify DNS servers  */
            c(
                "primary-v4" (  /* Primary IPv4 DNS server address */
                  ipv4addr  /* Primary IPv4 DNS server address */
                ),
                "secondary-v4" (  /* Secondary IPv4 DNS server address */
                  ipv4addr  /* Secondary IPv4 DNS server address */
                ),
                "primary-v6" (  /* Primary IPv6 DNS server address */
                  ipv6addr  /* Primary IPv6 DNS server address */
                ),
                "secondary-v6" (  /* Secondary IPv6 DNS server address */
                  ipv6addr  /* Secondary IPv6 DNS server address */
                )
            )
        ),
        "nbns-server" (  /* Specify NBNS servers  */
            c(
                "primary-v4" (  /* Primary IPv4 NBNS server address */
                  ipv4addr  /* Primary IPv4 NBNS server address */
                ),
                "secondary-v4" (  /* Secondary IPv4 NBNS server address */
                  ipv4addr  /* Secondary IPv4 NBNS server address */
                )
            )
        ),
        "p-cscf" arg  /* Specify IPv4 or IPv6 P-CSCF server */,
        "selection-mode" (  /* Specify APN access options */
            c(
                "no-subscribed"  /* Reject subscribed verified Users */,
                "from-ms"  /* Admit MS provided APN, subscription not verified */,
                "from-sgsn"  /* Admit Network provided APN, subscription not verified */
            )
        ),
        "service-selection-profile" arg  /* Service selection profile for this APN */,
        "network-behind-mobile" (  /* Specify IMSI nbm-address  */
            c(
                "imsi" arg (  /* Prefixes for a given IMSI */
                    c(
                        "prefix-v4" (  /* IPv4 Prefix Address */
                          ipv4prefix  /* IPv4 Prefix Address */
                        ),
                        "prefix-v6" (  /* IPv6 Prefix Address */
                          ipv6prefix  /* IPv6 Prefix Address */
                        )
                    )
                )
            )
        ),
        "service-mode" (  /* Service mode */
          ("maintenance")
        ),
        "call-rate-statistics" (  /* Call-rate-statistics options */
            c(
                "interval" arg  /* Time interval in minutes */,
                "history" arg  /* Number of intervals */
            )
        ),
        "pcef-profile" arg  /* PCEF profile for the apn */,
        "verify-source-address" (  /* UE address verification - default is enabled */
            c(
                "disable"  /* Disable UE address verification */
            )
        ),
        "inter-mobile-traffic" (  /* Inter mobile traffic redirect options */
            c(
                "redirect" (  /* Redirect options */
                    c(
                        "redirect-ip" (  /* Redirect destination address */
                          ipv4addr  /* Redirect destination address */
                        ),
                        c(
                          "routing-instance" arg  /* Routing instance used for redirect */
                        )
                    )
                ),
                "deny"  /* Do not allow inter mobile traffic */
            )
        )
    )
  )
end

