                                  ipv6prefix  /* Configure Locator Service for SRv6 */,
                                "block-length" arg  /* Block length associated with this locator */,
                                "function-length" arg  /* Function length associated with this locator */,
                                "static-function-max-entries" arg  /* Static function maximum entries */,
                                "micro-sid" (  /* Enable micro SID locator */
                                    c(
                                        "block-name" arg  /* Block name of micro SID locator */,
                                        "flavor" (  /* Flavor of micro SID locator */
                                            c(
                                                "psp"  /* Penultimate segment pop of the SRH */,
                                                "usp"  /* Ultimate segment pop of the SRH */,
                                                "usd"  /* Ultimate segment decapsulation */,
                                                "none"  /* No flavor */
                                            )
                                        ),
                                        "anycast"  /* Anycast locator */
                                    )
                                )
                            )
                        ),
                        "no-reduced-srh"  /* SRv6 Encapsulation mode non reduced SRH */,
                        "transit-srh-insert"  /* SRv6 SRH insert mode on transit */,
                        "no-psp"  /* Disable PSP */,
                        "traceoptions" (  /* Trace options for SRv6 process */
                            c(
                                "no-remote-trace"  /* Disable remote tracing */,
                                "file" (  /* Trace file information */
                                    sc(
                                          arg,
                                        "size" arg  /* Maximum trace file size */,
                                        "files" arg  /* Maximum number of trace files */,
                                        "world-readable"  /* Allow any user to read the log file */,
                                        "no-world-readable"  /* Don't allow any user to read the log file */,
                                        "match" (  /* Regular expression for lines to be logged */
                                          regular_expression  /* Regular expression for lines to be logged */
                                        )
                                    )
                                ).as(:oneline),
                                "flag" enum(("srv6-oam-recv" | "srv6-oam-err"))  /* Tracing parameters */.as(:oneline)
                            )
