                "charging-function-name" arg  /* Charging Function Name corresponds to PCRF referred online charging function name  */,
                "single-mscc"  /* Include only one MSCC AVP in CCR message */,
                "no-mscc-in-ccrt"  /* Do not include MSCC AVP in CCR-T message */,
                "no-initiate-session-on-activation"  /* Do not initiate diameter session on activation */,
                "quota-request-on-activation"  /* Request quota only on activation */,
