                    )
                ).as(:oneline),
                "time-limit" arg  /* The time-limit for container closure */,
                "exclude" (  /* Specify excluded signal triggers */
                    c(
                        "plmn-change"  /* No charging data updates on PLMN change */,
                        "qos-change"  /* No charging data updates on QOS change */,
                        "rat-change"  /* No charging data updates on RAT change */,
                        "sgsn-sgw-change"  /* No charging data updates on SGW change */,
                        "user-location-change"  /* No charging data updates on user location information change */,
                        "ms-timezone-change"  /* No charging data updates on MS-timezone change */,
                        "dcca-events"  /* No CDR generation on dcca-events like quota-exhaustion, threshold, etc  */
                    )
                )
            )
        ),
        "charging-method" (  /* Default charging method if not provided by PCEF */
          ("none" | "online" | "offline" | "both")
        ),
        "online" (
            c(
                "reporting-level" (  /* Default Reporting level for offline and online usage report */
                    c(
                        c(
                          "rating-group"  /* Rating group level reporting */,
                          "service-identifier"  /* Service identifier level reporting */
                        ),
                        "override"  /* Override reporting level provided by PCEF */
                    )
                ),
                "measurement-method" (  /* Default measurement method to use if not provided by PCEF */
                  ("none" | "volume" | "time" | "volume-and-time")
                ),
                "quota-threshold" (  /* Calculate quota threshold value as a percentage of total quota allocated */
                    c(
                          arg,
                        "override"  /* Override threshold value provided by OCS */
                    )
                ),
                "quota-validity-time" arg  /* Configure quota validity time if one is not provided by OCS */,
                "quota-holding-time" arg  /* Configure quota holding time if one is not provided by OCS */,
                "grant-quota" (  /* Configure grace-quota to be allocated in case of failure */
                    c(
                        "cc-time" arg  /* Configure time quota */,
                        "cc-octet-uplink" arg  /* Configure input volume quota */,
                        "cc-octet-downlink" arg  /* Configure output volume quota */,
                        "cc-octet-both" arg  /* Configure volume quota */
                    )
                ),
                "requested-service-unit" (  /* Determine the requested service unit AVP behavior */
                    c(
                        "include-quota-holding-time"  /* Include RSU when reporting reason is quota holding time */,
                        "cc-time" arg  /* Configure the time quota requested in CCR */,
                        "cc-octet-uplink" arg  /* Configure input volume quota */,
                        "cc-octet-downlink" arg  /* Configure output volume quota */,
                        "cc-octet-both" arg  /* Configure volume quota */
                    )
                ),
                "cc-failure-handling" (  /* Configure MobileNext handling during credit-control failure */
                    c(
                        "block-traffic-pending-reauth-no-quota"  /* Block traffic for a RG pending re-auth during quota exhaustion */,
                        "override"  /* Overrides charging failure-method provided by OCS */,
                        "result-code-based-action" (  /* Perform action based on diamter result-code AVP */
                            c(
                                "authorization-rejected" (  /* Diameter-authorization-rejected - default Terminate */
                                    c(
                                        c(
                                          "blacklist" (  /* Put rating-group in blacklist */
                                              sc(
                                                    arg
                                              )
                                          ).as(:oneline)
                                        )
                                    )
                                ),
                                "credit-control-not-applicable" (  /* Diameter-credit-control-not-applicable - default disable online charging */
                                    c(
                                        c(
                                          "convert-to-offline" (  /* Convert to offline in case of failure */
                                              c(
                                                  "grant-grace-quota"  /* Use offline charging till grace quota period */
                                              )
                                          )
                                        )
                                    )
                                ),
                                "end-user-service-denied" (  /* Diameter-end-user-service-denied - default terminate */
                                    c(
                                        c(
                                          "disable-online-charging"  /* Disable online charging. Continue to use offline charging if enabled otherwise no charging is applied */,
                                          "convert-to-offline" (  /* Convert to offline in case of failure */
                                              c(
                                                  "grant-grace-quota"  /* Use offline charging till grace quota period */
                                              )
                                          )
                                        )
                                    )
                                ),
                                "user-unknown" (  /* User-unknown - default terminate */
                                    c(
                                        c(
                                          "disable-online-charging"  /* Disable online charging. Continue to use offline charging if enabled otherwise no charging is applied */,
                                          "convert-to-offline" (  /* Convert to offline in case of failure */
                                              c(
                                                  "grant-grace-quota"  /* Use offline charging till grace quota period */
                                              )
                                          )
                                        )
                                    )
                                ),
                                "credit-limit-reached" (  /* Diameter-credit-limit-reached - default terminate */
                                    c(
                                        c(
                                          "blacklist" (  /* Put rating-group in blacklist */
                                              sc(
                                                    arg
                                              )
                                          ).as(:oneline)
                                        )
                                    )
                                )
                            )
                        ),
                        "initial-request" (  /* Failure action for initial cc request - default terminate */
                            c(
                                c(
                                  "grant-grace-quota"  /* Grant grace quota and continue online session */,
                                  "disable-online-charging"  /* Disable online charging. Continue to use offline charging if enabled otherwise no charging is applied */,
                                  "convert-to-offline" (  /* Convert to offline in case of failure */
                                      c(
                                          "grant-grace-quota"  /* Use offline charging till grace quota period */
                                      )
                                  )
                                )
                            )
                        ),
                        "update-request" (  /* Failure action for  update cc request - default terminate */
                            c(
                                c(
                                  "grant-grace-quota"  /* Grant grace quota and continue online session */,
                                  "disable-online-charging"  /* Disable online charging. Continue to use offline charging if enabled otherwise no charging is applied */,
                                  "convert-to-offline" (  /* Convert to offline in case of failure */
                                      c(
                                          "grant-grace-quota"  /* Use offline charging till grace quota period */
                                      )
                                  )
                                )
                            )
                        )
                    )
                )
            )
        )
    )
  )
end

