rule(:availability_check_profile) do
  arg.as(:arg) (
    c(
        "keepalive-method" (  /* How will availability check be done */
            sc(
                c(
                  "sip-options"  /* Check availability by sending a SIP OPTIONS message */
                )
            )
        ).as(:oneline),
        "keepalive-strategy" (  /* When will the server be checked for availability */
            sc(
                c(
                  "send-always" (  /* Always check the server availability */
                      c(
                          "failures-before-unavailable" arg  /* A server is assumed to be unavailable when a keepalive message was not answered this number of times */,
                          "successes-before-available" arg  /* A server is assumed to be available when a keepalive message was successfully answered this number of times */
                      )
                  ),
                  "send-when-unavailable" (  /* Check the server availability only when it is marked as unavailable */
                      sc(
                          "successes-before-available" arg  /* A server is assumed to be available when a keepalive message was successfully answered this number of times */
                      )
                  ).as(:oneline),
                  "do-not-send" (  /* Never perform availability checks of the server */
                      sc(
                          "blackout-period" arg  /* Time a server will be considered unavailable */
                      )
                  ).as(:oneline)
                )
            )
        ).as(:oneline),
        "keepalive-interval" (  /* How often should the server be checked for availability */
            c(
                "available-server" arg  /* How often should a server that is marked as available be checked for availablility */,
                "unavailable-server" arg  /* How often should a server that is marked as unavailable be checked for availablility */
            )
        ),
        "transaction-timeout" arg  /* A server is assumed to be unavailable when a keepalive message was not answered in this time */
    )
  )
end

