rule(:svc_ike_policy) do
  arg.as(:arg) (
    c(
        "description" arg  /* Text description of IKE policy */,
        "mode" (  /* Define the IKE first phase mode */
          ("main" | "aggressive")
        ),
        "version" (  /* Define the IKE version to use for the negotiation */
          ("1" | "2")
        ),
        "proposals" arg,
        "local-id" (  /* Define local identification */
            sc(
                c(
                  "ipv4_addr" (  /* One or more IPv4 address identification values */
                    ipv4addr  /* One or more IPv4 address identification values */
                  ),
                  "distinguished-name"  /* Use a distinguished name specified in local certificate */,
                  "fqdn" arg  /* One or more fully qualified domain name values */,
                  "key-id" arg  /* One or more key ID identification values */,
                  "ipv6-addr" (  /* One or more IPv6 address identification values */
                    ipv6addr  /* One or more IPv6 address identification values */
                  )
                )
            )
        ).as(:oneline),
        "certificate-policy-oids" arg  /* Allowed certificate policy object identifiers (maximum 5) */,
        "local-certificate" arg  /* Local certificate identifier */,
        "peer-certificate-type" (  /* Preferred type of certificate from peer */
          ("pkcs7" | "x509-signature")
        ),
        "remote-id" (  /* Define remote identification */
            c(
                "any-remote-id"  /* Allow any remote ID */,
                "ipv4_addr" (  /* One or more IPv4 address identification values */
                  ipv4addr  /* One or more IPv4 address identification values */
                ),
                "distinguished-name" (  /* One or more distinguished name values */
                    c(
                        "container" arg  /* One or more distinguished name container string */,
                        "wildcard" arg  /* One or more distinguished name wildcard string */,
                        "exact-match" arg  /* One or more distinguished name to do full length exact match */
                    )
                ),
                "fqdn" arg  /* One or more fully qualified domain name values */,
                "key-id" arg  /* One or more key ID identification values */,
                "ipv6-addr" (  /* One or more IPv6 address identification values */
                  ipv6addr  /* One or more IPv6 address identification values */
                )
            )
        ),
        "pre-shared-key" (  /* Define a preshared key */
            sc(
                c(
                  "ascii-text" arg  /* Format as text */,
                  "hexadecimal" arg  /* Format as hexadecimal */
                )
            )
        ).as(:oneline),
        "respond-bad-spi" (  /* Respond to IPSec packets with bad SPI values */
            sc(
                  arg
            )
        ).as(:oneline)
    )
  )
end

rule(:sw_rule_object) do
