                "syn-ack-ack-proxy" (  /* Configure syn-ack-ack proxy ids option */
                    sc(
                        "threshold" arg  /* Threshold */
                    )
                ).as(:oneline),
                "syn-flood" (  /* Configure SYN flood ids option */
                    c(
                        "alarm-threshold" arg  /* Alarm threshold */,
